\begin{definizione}[Taglio]
Un \emph{taglio} (\emph{cut}) $C$ di un grafo $G=(V,E)$ è un insieme di archi tale che
\begin{itemize}
  \item $C\subseteq E$;
  \item $(V,\,E\setminus C)$ è \emph{sconnesso}.
\end{itemize}
\end{definizione}

\begin{definizione}[Taglio minimo]
Un \emph{taglio minimo} (\emph{min-cut}) è un taglio $C$ tale che $\abs{C}$ è minima.
\end{definizione}

\paragraph{Probabilità condizionale.}
È lo strumento per minimizzare la probabilità di errore relativa a una \emph{sequenza} di scelte.

\begin{itemize}
  \item Se $\mathcal{E}_1$ ed $\mathcal{E}_2$ sono \emph{indipendenti}:
  \[
    \Pr[\mathcal{E}_1\cap\mathcal{E}_2]\;=\;\Pr[\mathcal{E}_1]\cdot\Pr[\mathcal{E}_2]
  \]
  \item Se non sono indipendenti (caso generale):
  \[
    \Pr[\mathcal{E}_1\cap\mathcal{E}_2]\;=\;\Pr[\mathcal{E}_1\mid\mathcal{E}_2]\cdot\Pr[\mathcal{E}_2]
  \]
  dove $\Pr[\mathcal{E}_1\mid\mathcal{E}_2]$ è la \emph{probabilità condizionata}: è ciò che ci consente
  di misurare la probabilità di due eventi \emph{consecutivi}.
\end{itemize}

\begin{figure}[H]\centering\input{tikz/prob-condizionata-venn.tikz}
\caption{A sinistra due eventi «che non si influenzano»; a destra il caso generale, con
$\mathcal{E}_1\cap\mathcal{E}_2\neq\emptyset$ evidenziata.}
\end{figure}

\begin{osservazione}
Nel disegno di sinistra i due eventi indipendenti sono rappresentati come regioni
\emph{disgiunte}: è solo un modo per suggerire che «non si influenzano a vicenda».
Attenzione però che l'indipendenza non ha una controparte insiemistica: due eventi disgiunti
di probabilità non nulla non sono mai indipendenti, perché
$\Pr[\mathcal{E}_1\cap\mathcal{E}_2]=0\neq\Pr[\mathcal{E}_1]\Pr[\mathcal{E}_2]$.
\end{osservazione}

Se invece di due eventi ne vogliamo misurare $k$, si itera la formula precedente e si ottiene la
\emph{regola della catena} (\emph{chain rule}):
\begin{align*}
  \Pr\!\left[\bigcap_{i=1}^{k}\mathcal{E}_i\right]
  ={}& \Pr[\mathcal{E}_1]\cdot\Pr[\mathcal{E}_2\mid\mathcal{E}_1]\cdot
       \Pr[\mathcal{E}_3\mid\mathcal{E}_2\cap\mathcal{E}_1]\cdot{}\\
     & \cdots\cdot
       \Pr\!\left[\mathcal{E}_k\;\middle|\;\bigcap_{i=1}^{k-1}\mathcal{E}_i\right].
\end{align*}

\paragraph{Idea per introdurre le «scelte» (random).}
Si sceglie a caso un arco del grafo e lo si \emph{contrae}: i due estremi $u$ e $v$ vengono fusi
in un unico nodo $uv$, che eredita tutti gli archi incidenti a $u$ o a $v$. Due accorgimenti:
\begin{itemize}
  \item se la contrazione forma un \emph{self-loop}, lo si ignora (viene eliminato);
  \item gli archi paralleli fra due nodi distinti si mantengono invece tutti: si lavora perciò
        su \emph{multigrafi}, cioè su grafi in cui fra due nodi possono esserci più archi.
\end{itemize}

